// WavefunctionAnalyzer: U(3) and U(4) content of eigenstates saved by
// MatrixOperatorJT, without recomputing anything.
//
// For each of the lowest states it prints, in every N hw excitation, the
// probability (%) of each U(3) irrep (spatial symmetry, deformation) and each
// U(4) irrep (spin-isospin supermultiplet), with their Casimir C2.
//
// First run MatrixOperatorJT with write = true (its default). The settings
// below must be the same as in that run: the eigenvector components are
// indexed by its basis. The defaults match MatrixOperatorJT's defaults.
//
// Do not edit this file; copy it into app/work/ and edit the copy:
//   cp app/tutorial/WavefunctionAnalyzer.cpp app/work/
//   make -j 8 apps && mpirun -np 1 bin/work/WavefunctionAnalyzer

#include <algorithm>
#include <chrono>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

#include <print.h>
#include <readwrite.h>

#include <sam.h>
#include <OperatorJT.h>
#include <WavefunctionAnalyzer.h>

int main(int argc, char* argv[])
{
  using utils::print;

  sam::initialize(&argc, &argv);

  ////////////// SETTINGS //////////////

  // as in the MatrixOperatorJT run that saved the eigenpairs:
  int Z = 3, N = 3, JJ = 2, Nmax = 4, hw = 20;
  std::string name = "Hamiltonian with N2LO_opt_bare";
  bool truncate = false;   // the isospin truncation of MatrixOperatorJT
  int TT = 0;

  int n_states = 2;        // number of lowest states to analyze

  ////////////// DON'T EDIT ANYTHING BELOW //////////////

#ifdef USE_MPI
  int mpi_rank = 0;
  MPI_Comm_rank(MPI_COMM_WORLD, &mpi_rank);
  const bool root = (mpi_rank == 0);
#else
  const bool root = true;
#endif

  std::vector<U3xU4::hw_subspace> subspaces;
  if (truncate)
    for (int n = Nmax % 2; n <= Nmax; n += 2)
      subspaces.emplace_back(n, u3::irreps{}, u4::irreps{},
                             std::vector<HO::qn_t>{},
                             std::vector<HO::qn_t>{static_cast<HO::qn_t>(TT)});
  U3xU4::ManyNucleonBasis basis(N, Z, Nmax, JJ, subspaces);
  basis.construct();

  if (root)
  {
    print("Z = {}, N = {}, J = {}/2, Nmax = {}, hw = {} MeV, {}\n", Z, N, JJ,
          Nmax, hw, truncate ? "truncated" : "full space");
    print("Basis dimension: {}\n", basis.dim());

    HO::Table_nljmjmt HO_labels(basis.maxShell());
    U3xU4::Table_gelfand gelfand_labels(basis.maxShell());

    // the operator only locates the file of the eigenpairs:
    JT::Operator op(name, N, Z, hw, Nmax, HO_labels, gelfand_labels);
    auto wfns_file = truncate
        ? op.wfns_file(basis, "Truncation_TT" + std::to_string(TT))
        : op.wfns_file(basis);
    auto [evals, evecs] = utils::readEigenPairs(wfns_file);

    if (static_cast<size_t>(evecs.rows()) != basis.dim())
      throw std::runtime_error(
          "Sorry, the eigenvectors in " + wfns_file + " have " +
          std::to_string(evecs.rows()) + " components, but the basis has " +
          std::to_string(basis.dim()) + " states; use the settings of the "
          "MatrixOperatorJT run that wrote them");

    print("Eigenvalues (MeV):\n");
    for (size_t i = 0; i < evals.size(); i++)
      print("  {:3}  {:14.6f}\n", i, evals[i]);

    n_states = std::min<int>(n_states, evecs.cols());
    print("U(3) and U(4) probabilities of the lowest {} states:\n", n_states);

    auto t0 = std::chrono::steady_clock::now();

    for (const auto& subspace :
         sam::U3_wavefunction_analyzer(basis, evecs, n_states))
      std::cout << subspace << std::endl;

    for (const auto& subspace :
         sam::U4_wavefunction_analyzer(basis, evecs, n_states))
      std::cout << subspace << std::endl;

    std::chrono::duration<double> t = std::chrono::steady_clock::now() - t0;
    print("Time: {:.1f} s\n", t.count());
  }

  sam::finalize();
}
